def _inverse(path,raw,expected,edits):
 raw=code_delta.reduce_if_selected(path,raw)
 if path not in expected or type(raw)is not bytes or hashlib.sha256(raw).hexdigest()!=SOURCE_INPUTS[path]:raise ValueError('unreviewed Conduit source')
 if path in oauth_delta.SOURCE_INPUTS:raw=oauth_delta.reduce_current(path,raw)
 for added,removed in edits[path]:
  if raw.count(added)!=1:raise ValueError('Conduit source inverse shape changed')
  raw=raw.replace(added,removed,1)
 if hashlib.sha256(raw).hexdigest()!=expected[path]:raise ValueError('Conduit changed other historical bytes')
 return raw
def reduce_owner(path,raw):return _inverse(path,raw,BASE_PINS,EDITS)
